import { BrowserRouter, Routes, Route } from 'react-router-dom';

import BuilderPage from './pages/BuilderPage';
import FormPage from './pages/FormPage';

function App() {
  return (
    <BrowserRouter>
      <Routes>

        <Route
          path="/"
          element={<BuilderPage />}
        />

        <Route
          path="/form"
          element={<FormPage />}
        />

      </Routes>
    </BrowserRouter>
  );
}

export default App;
